    direktur:{label:'Direktur',report:'Laporan Direktur',reportCadence:'Bulanan → Yayasan',meeting:'direksi',observation:'Program pesantren & Supervisor',mandates:[['Arah Strategis','Menentukan arah dan prioritas strategis pesantren.'],['Pembinaan Supervisor','Memastikan Supervisor mampu mengendalikan bidang secara optimal.'],['Observasi Mutu','Mengobservasi pelaksanaan program dan proses supervisi secara langsung.'],['Rapat Direksi','Menyelenggarakan evaluasi/koordinasi rutin bersama Supervisor.'],['Laporan Yayasan','Menyusun laporan bulanan berbasis data untuk Yayasan.'],['Pengembangan Kompetensi','Mendorong pelatihan dan coaching bertahap bagi Supervisor.']]},
    supervisor:{label:'Supervisor',report:'Laporan Supervisi',reportCadence:'Pekanan → Direktur',meeting:'supervisi',observation:'Program divisi & Manajer',mandates:[['Kendali Divisi','Membina Manajer agar tugas divisi terlaksana optimal.'],['Observasi Program','Melihat pelaksanaan dan mutu program pada bidang yang diawasi.'],['Observasi Manajerial','Mengobservasi cara Manajer memimpin dan menindaklanjuti masalah.'],['Rapat Supervisi','Rapat pekanan bersama Manajer untuk evaluasi dan koordinasi.'],['Laporan Direktur','Menyampaikan laporan pekanan kepada Direktur.'],['Pembinaan Manajer','Menjalankan coaching/pelatihan rutin untuk Manajer.']]},
