  function applyAgendaCandidates(){const vals=[...document.querySelectorAll('.agendaCandidate:checked')].map(x=>x.value);if(!vals.length){toast('Pilih kandidat agenda terlebih dahulu.');return}const ta=$('meetingAgenda');ta.value=[ta.value.trim(),...vals.map((v,i)=>`${i+1}. ${v}`)].filter(Boolean).join('\n');toast('Kandidat agenda dimasukkan.')}
  async function saveMeeting(){const id=$('meetingId').value||db.ref(`${ROOT}/meetings`).push().key,title=$('meetingTitle').value.trim();if(!title){toast('Judul rapat wajib diisi.');return}const old=data.meetings.find(x=>x.id===id)||{},rows=collectMeetingFollowRows();showLoader('Menyimpan rapat dan tindak lanjut...');try{const centralIds=[];for(const row of rows){const fid=row.centralId||db.ref(`${ROOT}/followups`).push().key,pu=getUserByUsername(row.pic);centralIds.push(fid);const previous=data.followups.find(f=>f.id===fid)||{};await db.ref(`${ROOT}/followups/${fid}`).set({task:row.task,sourceType:'rapat',sourceId:id,sourceTitle:title,division:$('meetingDivision').value,pic:row.pic,picName:pu?.label||pu?.nama||row.pic,deadline:row.deadline,priority:'sedang',status:row.status||'baru',createdAt:previous.createdAt||nowIso(),createdBy:previous.createdBy||createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()});if(row.pic&&row.pic!==previous.pic)await notifyUser(row.pic,'Tindak Lanjut Rapat Baru',`${title}: ${row.task}`,'main-dashboard.html?operasional=followups')}const stale=data.followups.filter(f=>f.sourceType==='rapat'&&f.sourceId===id&&!centralIds.includes(f.id));await Promise.all(stale.map(f=>db.ref(`${ROOT}/followups/${f.id}`).remove()));const payload={meetingType:$('meetingType').value,purpose:$('meetingPurpose').value,title,date:$('meetingDate').value,time:$('meetingTime').value,division:$('meetingDivision').value,place:$('meetingPlace').value.trim(),leader:$('meetingLeader').value.trim(),minuteTaker:$('meetingMinuteTaker').value.trim(),participants:$('meetingParticipants').value.split(',').map(x=>x.trim()).filter(Boolean),agenda:$('meetingAgenda').value.trim(),discussion:$('meetingDiscussion').value.trim(),decision:$('meetingDecision').value.trim(),followupIds:centralIds,createdAt:old.createdAt||nowIso(),createdBy:old.createdBy||createdMeta(),updatedAt:nowIso(),updatedBy:createdMeta()};await db.ref(`${ROOT}/meetings/${id}`).set(payload);closeForm();toast('Rapat dan tindak lanjut tersimpan.')}catch(e){alert('Rapat belum tersimpan: '+e.message)}finally{hideLoader()}}
  function openMeetingDetail(id){const x=data.meetings.find(a=>a.id===id);if(!x)return;const linked=data.followups.filter(f=>f.sourceType==='rapat'&&f.sourceId===id);$('detailKicker').textContent=`${MEETING_LABELS[x.meetingType]||'RAPAT'} • ${PURPOSE_LABELS[x.purpose]||''}`;$('detailTitle').textContent=x.title||'Rapat';$('detailBody').innerHTML=`<div class="detail-block"><small>Informasi Rapat</small><p>${fmtDate(x.date)}${x.time?' • '+x.time:''}\n${esc(x.place||'-')}\nPimpinan: ${esc(x.leader||'-')}\nPeserta: ${esc((x.participants||[]).join(', ')||'-')}</p></div><div class="detail-block"><small>Agenda</small><p>${esc(x.agenda||'-')}</p></div><div class="detail-block"><small>Pembahasan</small><p>${esc(x.discussion||'-')}</p></div><div class="detail-block"><small>Keputusan</small><p>${esc(x.decision||'-')}</p></div><div class="detail-block"><small>Tindak Lanjut</small><p>${linked.length?linked.map((f,i)=>`${i+1}. ${f.task} — ${f.picName||f.pic||'-'} — ${STATUS_LABELS[statusOf(f)]||statusOf(f)}`).join('\n'):'Belum ada tindak lanjut.'}</p></div><div class="form-actions"><button class="btn soft" onclick="Operational.closeDetail()">Tutup</button><button class="btn soft" onclick="window.print()">Cetak</button><button class="btn gold" onclick="Operational.closeDetail();Operational.openMeetingForm('${esc(id)}')">Edit</button></div>`;modalOpen('detailModal')}

  function renderFollowups(){const q=String($('followupSearch')?.value||'').toLowerCase(),sf=$('followupStatusFilter')?.value||'',src=$('followupSourceFilter')?.value||'';const arr=scoped('followups').filter(x=>(!sf||statusOf(x)===sf)&&(!src||x.sourceType===src)&&(!q||[x.task,x.picName,x.pic,x.sourceTitle,x.division].join(' ').toLowerCase().includes(q)));$('followupList').innerHTML=arr.length?arr.map(x=>recordCard({chips:[statusChip(statusOf(x)),`<span class="chip blue">${esc(SOURCE_LABELS[x.sourceType]||x.sourceType||'Manual')}</span>`,priorityChip(x.priority)],date:x.deadline?`Deadline ${fmtDate(x.deadline)}`:'Tanpa deadline',title:x.task||'Tindak Lanjut',desc:x.sourceTitle?`Sumber: ${x.sourceTitle}`:'',foot:`<span>PIC: ${esc(x.picName||x.pic||'-')}</span><select class="status-select" onclick="event.stopPropagation()" onchange="Operational.updateFollowupStatus('${esc(x.id)}',this.value)"><option value="baru" ${!x.status||x.status==='baru'?'selected':''}>Baru</option><option value="proses" ${x.status==='proses'?'selected':''}>Proses</option><option value="selesai" ${x.status==='selesai'?'selected':''}>Selesai</option></select>`})).join(''):empty('Belum ada tindak lanjut yang sesuai filter.')}
  async function updateFollowupStatus(id,status){await db.ref(`${ROOT}/followups/${id}`).update({status,updatedAt:nowIso(),updatedBy:createdMeta()});toast('Status tindak lanjut diperbarui.')}

  function reportMetrics(start='',end=''){const pick=(kind)=>{const arr=scoped(kind);return start&&end?arr.filter(x=>inPeriod(x,start,end)):arr};const tasks=pick('tasks'),obs=pick('observations'),meet=pick('meetings'),fol=pick('followups');return{tasks:tasks.length,tasksDone:tasks.filter(x=>statusOf(x)==='selesai').length,observations:obs.length,findings:obs.filter(x=>['yellow','red'].includes(x.signal)).length,meetings:meet.length,followups:fol.length,followupsDone:fol.filter(x=>statusOf(x)==='selesai').length,overdue:[...tasks,...fol].filter(x=>statusOf(x)==='terlambat').length}}
  function autoReportSummary(m){m=m||reportMetrics();const pct=m.followups?Math.round(m.followupsDone/m.followups*100):0;return `Periode ini tercatat ${m.tasks} tugas operasional dengan ${m.tasksDone} selesai. Dilakukan ${m.observations} observasi dengan ${m.findings} temuan yang memerlukan perhatian/tindakan. Terdapat ${m.meetings} rapat operasional dan ${m.followups} tindak lanjut dengan tingkat penyelesaian ${pct}%. Terdapat ${m.overdue} item yang melewati deadline dan perlu diprioritaskan.`}
  function renderReports(){const q=String($('reportSearch')?.value||'').toLowerCase(),pf=$('reportPeriodFilter')?.value||'';const arr=scoped('reports').filter(x=>(!pf||String(x.period||'').startsWith(pf))&&(!q||[x.title,x.summary,x.achievements,x.obstacles,x.priorities].join(' ').toLowerCase().includes(q)));$('reportList').innerHTML=arr.length?arr.map(x=>recordCard({chips:[`<span class="chip blue">${esc(x.reportType||LEVELS[level]?.report||'Laporan')}</span>`,`<span class="chip">${esc(x.periodLabel||x.period||'-')}</span>`],date:fmtDate((x.createdAt||'').slice(0,10)),title:x.title||'Laporan Operasional',desc:x.summary||'',foot:`<span>${esc(x.authorName||x.createdBy?.name||'-')}</span><span>${esc(x.division||'-')}</span>`,onclick:`Operational.openReportDetail('${esc(x.id)}')`})).join(''):empty('Belum ada laporan operasional.')}
  function openReportForm(){const info=LEVELS[level]||LEVELS['staf-mula'];const end=today(),start=level==='direktur'?`${today().slice(0,7)}-01`:addDays(today(),-6),m=reportMetrics(start,end),period=level==='direktur'?today().slice(0,7):`${start}_${end}`;const label=level==='direktur'?new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(new Date(today()+'T00:00:00')):`Pekan ${fmtDate(start)} – ${fmtDate(end)}`;$('formKicker').textContent='LAPORAN BERJENJANG';$('formTitle').textContent=info.report;$('formBody').innerHTML=`<div class="form-grid"><div class="field"><label>Jenis Laporan</label><input class="control" id="reportType" value="${esc(info.report)}" readonly></div><div class="field"><label>Periode</label><input class="control" id="reportPeriodLabel" value="${esc(label)}"></div><div class="field"><label>Bidang</label><select class="control" id="reportDivision">${divisionOptions(division,true)}</select></div><div class="field"><label>Tujuan Laporan</label><input class="control" id="reportDestination" value="${esc(level==='direktur'?'Yayasan':managerName()|| (level==='supervisor'?'Direktur':level==='manajer'?'Supervisor':'Manajer'))}"></div><div class="field full"><label>Ringkasan Otomatis</label><textarea class="control" id="reportSummary">${esc(autoReportSummary(m))}</textarea></div><div class="field full"><label>Capaian Positif</label><textarea class="control" id="reportAchievements" placeholder="Apa yang berjalan baik? atau koreksi ringkasan otomatis…"></textarea></div><div class="field full"><label>Hambatan / Risiko</label><textarea class="control" id="reportObstacles" placeholder="Hambatan utama yang membutuhkan perhatian…"></textarea></div><div class="field full"><label>Prioritas Periode Berikutnya</label><textarea class="control" id="reportPriorities" placeholder="Fokus kerja berikutnya…"></textarea></div><div class="field full"><label>Keputusan / Dukungan yang Dibutuhkan</label><textarea class="control" id="reportSupport" placeholder="Dukungan dari atasan/Yayasan bila diperlukan…"></textarea></div><input type="hidden" id="reportPeriod" value="${esc(period)}"></div><div class="form-actions"><button class="btn soft" onclick="Operational.closeForm()">Batal</button><button class="btn primary" onclick="Operational.saveReport()">Simpan Laporan</button></div>`;modalOpen('formModal')}
  async function saveReport(){const id=db.ref(`${ROOT}/reports`).push().key,rawPeriod=$('reportPeriod').value,range=rawPeriod.includes('_')?rawPeriod.split('_'):[rawPeriod+'-01',today()],m=reportMetrics(range[0],range[1]),payload={reportType:$('reportType').value,title:`${$('reportType').value} • ${$('reportPeriodLabel').value}`,period:$('reportPeriod').value,periodLabel:$('reportPeriodLabel').value,division:$('reportDivision').value,destination:$('reportDestination').value,destinationUsername:String(profile.atasanOperasional||profile.operationalSupervisor||''),summary:$('reportSummary').value.trim(),achievements:$('reportAchievements').value.trim(),obstacles:$('reportObstacles').value.trim(),priorities:$('reportPriorities').value.trim(),support:$('reportSupport').value.trim(),metrics:m,author:username(),authorName:displayName(),authorRole:activeRole,authorLevel:level,createdAt:nowIso(),createdBy:createdMeta(),updatedAt:nowIso()};showLoader('Menyimpan laporan...');try{await db.ref(`${ROOT}/reports/${id}`).set(payload);closeForm();toast('Laporan operasional disimpan.')}catch(e){alert('Laporan belum tersimpan: '+e.message)}finally{hideLoader()}}
  function openReportDetail(id){const x=data.reports.find(a=>a.id===id);if(!x)return;const m=x.metrics||{};$('detailKicker').textContent='LAPORAN OPERASIONAL';$('detailTitle').textContent=x.title||'Laporan';$('detailBody').innerHTML=`<article class="report-preview"><h2>${esc(x.reportType||'Laporan Operasional')}</h2><div class="report-meta">${esc(x.periodLabel||x.period||'-')} • ${esc(x.division||'-')} • kepada ${esc(x.destination||'-')}</div><div class="report-section"><div class="report-kpis"><div class="report-kpi"><span>Tugas</span><b>${m.tasks??0}</b></div><div class="report-kpi"><span>Observasi</span><b>${m.observations??0}</b></div><div class="report-kpi"><span>Rapat</span><b>${m.meetings??0}</b></div><div class="report-kpi"><span>Tindak Lanjut</span><b>${m.followups??0}</b></div></div></div><div class="report-section"><h3>Executive Summary</h3><p>${esc(x.summary||'-')}</p></div><div class="report-section"><h3>Capaian Positif</h3><p>${esc(x.achievements||'-')}</p></div><div class="report-section"><h3>Hambatan / Risiko</h3><p>${esc(x.obstacles||'-')}</p></div><div class="report-section"><h3>Prioritas Berikutnya</h3><p>${esc(x.priorities||'-')}</p></div><div class="report-section"><h3>Dukungan / Keputusan yang Dibutuhkan</h3><p>${esc(x.support||'-')}</p></div><div class="report-section"><p>Disusun oleh ${esc(x.authorName||'-')}.</p></div></article><div class="form-actions"><button class="btn soft" onclick="Operational.closeDetail()">Tutup</button><button class="btn primary" onclick="window.print()">Cetak / PDF</button></div>`;modalOpen('detailModal')}

  function todayActivitySummary(){const t=today();return{tasksDone:data.tasks.filter(x=>x.status==='selesai'&&String(x.updatedAt||'').startsWith(t)).length,observations:data.observations.filter(x=>x.date===t).length,meetings:data.meetings.filter(x=>x.date===t).length,followupsDone:data.followups.filter(x=>x.status==='selesai'&&String(x.updatedAt||'').startsWith(t)).length}}
  function renderJournals(){const q=String($('journalSearch')?.value||'').toLowerCase(),scope=$('journalScopeFilter')?.value||'saya';const arr=scoped('journals').filter(x=>((scope==='tim'&&['direktur','supervisor','manajer'].includes(level))||x.username===username())&&(!q||[x.note,x.tomorrowFocus,x.name,x.division].join(' ').toLowerCase().includes(q)));$('journalList').innerHTML=arr.length?arr.map(x=>{const a=x.activity||{};return recordCard({chips:[`<span class="chip blue">${esc(x.name||x.username||'-')}</span>`,`<span class="chip">${esc(x.division||'-')}</span>`],date:fmtDate(x.date),title:`Jurnal ${fmtDate(x.date)}`,desc:x.note||'Tidak ada catatan tambahan.',foot:`<span>✓ ${a.tasksDone||0} tugas • ◉ ${a.observations||0} observasi • ✎ ${a.meetings||0} rapat</span><span>Fokus: ${esc(x.tomorrowFocus||'-')}</span>`})}).join(''):empty('Belum ada jurnal operasional.')}
  function openJournalForm(){const act=todayActivitySummary(),existing=data.journals.find(x=>x.username===username()&&x.date===today())||{};$('formKicker').textContent='JURNAL OPERASIONAL';$('formTitle').textContent='Jurnal Hari Ini';$('formBody').innerHTML=`<div class="form-grid"><div class="field"><label>Tanggal</label><input class="control" value="${fmtDate(today())}" readonly></div><div class="field"><label>Ringkasan Aktivitas</label><input class="control" value="${act.tasksDone} tugas selesai • ${act.observations} observasi • ${act.meetings} rapat • ${act.followupsDone} tindak lanjut selesai" readonly></div><div class="field full"><label>Catatan Hari Ini</label><textarea class="control" id="journalNote" placeholder="Hal penting, hambatan, pembelajaran…">${esc(existing.note||'')}</textarea></div><div class="field full"><label>Fokus Besok</label><textarea class="control" id="journalTomorrow" placeholder="Prioritas utama berikutnya…">${esc(existing.tomorrowFocus||'')}</textarea></div></div><div class="form-actions"><button class="btn soft" onclick="Operational.closeForm()">Batal</button><button class="btn green" onclick="Operational.saveJournal()">Simpan Jurnal</button></div>`;modalOpen('formModal')}
  async function saveJournal(){const id=`${safeKey(username())}_${today()}`,activity=todayActivitySummary(),payload={date:today(),username:username(),name:displayName(),role:activeRole,level,division,activity,note:$('journalNote').value.trim(),tomorrowFocus:$('journalTomorrow').value.trim(),updatedAt:nowIso(),createdAt:data.journals.find(x=>x.id===id)?.createdAt||nowIso()};await db.ref(`${ROOT}/journals/${id}`).set(payload);closeForm();toast('Jurnal hari ini disimpan.')}

  function renderCompetencies(){const q=String($('competencySearch')?.value||'').toLowerCase(),sf=$('competencyStatusFilter')?.value||'';const arr=scoped('competencies').filter(x=>(!sf||x.status===sf)&&(!q||[x.personName,x.person,x.competency,x.programType,x.notes].join(' ').toLowerCase().includes(q)));$('competencyList').innerHTML=arr.length?arr.map(x=>recordCard({chips:[statusChip(x.status),`<span class="chip purple">${esc(x.programType||'Pengembangan')}</span>`],date:x.targetDate?`Target ${fmtDate(x.targetDate)}`:'',title:x.competency||'Pengembangan Kompetensi',desc:`${x.personName||x.person||'-'} • ${x.notes||''}`,foot:`<span>Pembina: ${esc(x.coachName||'-')}</span><select class="status-select" onclick="event.stopPropagation()" onchange="Operational.updateCompetencyStatus('${esc(x.id)}',this.value)"><option value="direncanakan" ${x.status==='direncanakan'?'selected':''}>Direncanakan</option><option value="berjalan" ${x.status==='berjalan'?'selected':''}>Berjalan</option><option value="selesai" ${x.status==='selesai'?'selected':''}>Selesai</option></select>`})).join(''):empty('Belum ada program pengembangan kompetensi.')}
  function openCompetencyForm(){const defaultType=level==='direktur'?'Coaching Supervisor':level==='supervisor'?'Coaching Manajer':level==='manajer'?'Pembinaan Staf':'Pengembangan Diri';$('formKicker').textContent='PENGEMBANGAN KOMPETENSI';$('formTitle').textContent='Program Pengembangan';$('formBody').innerHTML=`<div class="form-grid"><div class="field"><label>Personil</label><select class="control" id="competencyPerson">${userOptions('',true,preferredPeople())}</select></div><div class="field"><label>Jenis Program</label><select class="control" id="competencyType"><option>Coaching</option><option>Pelatihan</option><option>Mentoring</option><option>Microteaching</option><option>Observasi Terarah</option><option>${esc(defaultType)}</option></select></div><div class="field full"><label>Kompetensi yang Dikembangkan</label><input class="control" id="competencyName" placeholder="Contoh: Manajemen Rapat, Supervisi, Komunikasi, Kedisiplinan…"></div><div class="field"><label>Target Selesai</label><input class="control" type="date" id="competencyTarget" value="${addDays(today(),30)}"></div><div class="field"><label>Status</label><select class="control" id="competencyStatus"><option value="direncanakan">Direncanakan</option><option value="berjalan">Berjalan</option><option value="selesai">Selesai</option></select></div><div class="field full"><label>Catatan / Target Perilaku</label><textarea class="control" id="competencyNotes" placeholder="Perubahan kompetensi yang ingin terlihat…"></textarea></div></div><div class="form-actions"><button class="btn soft" onclick="Operational.closeForm()">Batal</button><button class="btn gold" onclick="Operational.saveCompetency()">Simpan Program</button></div>`;modalOpen('formModal')}
  async function saveCompetency(){const person=$('competencyPerson').value,pu=getUserByUsername(person),name=$('competencyName').value.trim();if(!person||!name){toast('Personil dan kompetensi wajib dipilih.');return}const id=db.ref(`${ROOT}/competencies`).push().key,payload={person,personName:pu?.label||pu?.nama||person,programType:$('competencyType').value,competency:name,targetDate:$('competencyTarget').value,status:$('competencyStatus').value,notes:$('competencyNotes').value.trim(),coach:username(),coachName:displayName(),coachRole:activeRole,coachLevel:level,division:pu?.divisiOperasional||pu?.divisi||division,createdAt:nowIso(),createdBy:createdMeta(),updatedAt:nowIso()};await db.ref(`${ROOT}/competencies/${id}`).set(payload);await notifyUser(person,'Program Pengembangan Kompetensi',`${displayName()} menetapkan pengembangan: ${name}`,'main-dashboard.html?operasional=competencies');closeForm();toast('Program pengembangan disimpan.')}
  async function updateCompetencyStatus(id,status){await db.ref(`${ROOT}/competencies/${id}`).update({status,updatedAt:nowIso(),updatedBy:createdMeta()});toast('Status pengembangan diperbarui.')}

  async function notifyUser(user,title,desc,link){if(!user)return;try{const ref=db.ref(`cahaya_app/notifikasi_user/${safeKey(user)}`).push();await ref.set({title,desc,link,dibaca:false,createdAt:nowIso(),source:'manajemen_operasional'})}catch(e){console.warn('Push notification helper',e)}}

  function handleDeepLink(){const qs=new URLSearchParams(location.search),v=qs.get('view');if(v&&document.getElementById('view-'+v))navigate(v)}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeForm();closeDetail()}});

